"""Simple matcher module for the Wizard-of-Oz prototype.

This file contains a small `WIZARD_MAP` and helper functions that
simulate analysis and return pre-canned matches. Keep logic here so
`app.py` remains UI-only.
"""
import os

# Map demo inspiration filename -> list of marketplace image paths
WIZARD_MAP = {
	"inspo1.jpg": ["data/matches/inspo1_1.jpg", "data/matches/inspo1_2.jpg"],
	"inspo2.jpg": ["data/matches/inspo2_1.jpg", "data/matches/inspo2_2.jpg"],
	"inspo3.jpg": ["data/matches/inspo3_1.jpg", "data/matches/inspo3_2.jpg"],
}

def list_demo_inspirations(folder="data/inspiration"):
	if not os.path.isdir(folder):
		return []
	return sorted([f for f in os.listdir(folder) if f.lower().endswith((".jpg", ".jpeg", ".png"))])

def simulate_analysis(filename_or_bytes):
	"""Return a simulated attribute/confidence dict for UI display.

	`filename_or_bytes` can be a name or an uploaded file-like object.
	"""
	# Simple fixed output for demo purposes
	return {"Suede": 0.6, "Earth Tones": 0.4, "Oversized": 0.7}

def get_matches_for_filename(filename):
	"""Return the list of match image paths for a demo filename.

	If no mapping exists, return an empty list.
	"""
	return WIZARD_MAP.get(filename, [])

import streamlit as st
from PIL import Image
import os
from src import matcher

st.set_page_config(layout="wide", page_title="Thread-Trace")

st.title("Thread-Trace — Mood → Marketplace")

uploaded = st.file_uploader("Drag & drop your Pinterest / mood image", type=["jpg","jpeg","png"]) 

tab1, tab2, tab3 = st.tabs(["Inspiration", "AI Analysis", "Matches"])

with tab1:
	if uploaded:
		st.image(Image.open(uploaded), use_column_width=True)
	else:
		st.write("Demo inspirations (click to upload one locally if you want):")
		demo_list = matcher.list_demo_inspirations()
		if demo_list:
			cols = st.columns(min(3, len(demo_list)))
			for i, fname in enumerate(demo_list[:3]):
				cols[i].image(os.path.join("data/inspiration", fname), caption=fname)
		else:
			st.info("No demo images found in data/inspiration. Add 3–4 sample images named inspo1.jpg, inspo2.jpg, etc.")

with tab2:
	if uploaded:
		st.subheader("Quick AI Analysis")
		analysis = matcher.simulate_analysis(uploaded.name)
		for k, v in analysis.items():
			st.write(f"- {k}: {int(v*100)}%")
		with st.expander("Technical Breakdown"):
			st.write("Feature vector and nearest-neighbor search (simulated).")
	else:
		st.info("Upload a demo image to see simulated analysis.")

with tab3:
	st.header("Marketplace Matches")
	matched = []
	if uploaded:
		matched = matcher.get_matches_for_filename(uploaded.name)
	else:
		# show a few demo matches
		matched = sum(matcher.WIZARD_MAP.values(), [])[:4]

	if not matched:
		st.write("No matches found. Add demo matches to data/matches and map filenames in src/matcher.py")
	else:
		cols = st.columns(4)
		for i, img_path in enumerate(matched):
			try:
				cols[i%4].image(img_path, use_column_width=True)
				cols[i%4].caption(os.path.basename(img_path))
			except Exception:
				cols[i%4].write("Missing demo image: " + img_path)

"""Simple matcher module for the Wizard-of-Oz prototype.

This file contains a small `WIZARD_MAP` and helper functions that
simulate analysis and return pre-canned matches. Keep logic here so
`app.py` remains UI-only.
"""
import os
import json

# Map demo inspiration filename -> list of marketplace image paths
WIZARD_MAP = {
	"inspo1.jpg": ["data/matches/inspo1_1.jpg", "data/matches/inspo1_2.jpg"],
	"inspo2.jpg": ["data/matches/inspo2_1.jpg", "data/matches/inspo2_2.jpg"],
	"inspo3.jpg": ["data/matches/inspo3_1.jpg", "data/matches/inspo3_2.jpg"],
}

def list_demo_inspirations(folder="data/inspiration"):
	if not os.path.isdir(folder):
		return []
	return sorted([f for f in os.listdir(folder) if f.lower().endswith((".jpg", ".jpeg", ".png"))])

def simulate_analysis(filename_or_bytes):
	"""Return a simulated attribute/confidence dict for UI display.

	`filename_or_bytes` can be a name or an uploaded file-like object.
	"""
	# Simple fixed output for demo purposes
	return {"Suede": 0.6, "Earth Tones": 0.4, "Oversized": 0.7}

def get_matches_for_filename(filename):
	"""Return the list of match image paths for a demo filename.

	If no mapping exists, return an empty list.
	"""
	return WIZARD_MAP.get(filename, [])


def load_matches_for(filename):
	"""Load structured match metadata for `filename` from data/matches/<base>.json.

	If the JSON file is present, it should contain a list of objects with keys:
	`img` (url or local path), `url` (marketplace link), `title`, `price`, `source`.

	If the JSON file is missing, fall back to `WIZARD_MAP` and return list of dicts
	with `img` populated and other fields empty.
	"""
	if not filename:
		return []
	base = os.path.splitext(filename)[0]
	json_path = os.path.join("data", "matches", f"{base}.json")
	if os.path.exists(json_path):
		try:
			with open(json_path, "r", encoding="utf8") as fh:
				data = json.load(fh)
				if isinstance(data, list):
					return data
		except Exception:
			return []

	# fallback to WIZARD_MAP entries (local image paths)
	imgs = WIZARD_MAP.get(filename, [])
	return [{"img": p, "url": "", "title": os.path.basename(p), "price": "", "source": ""} for p in imgs]

import streamlit as st
from PIL import Image
import os
from src import matcher

st.set_page_config(layout="wide", page_title="Thread-Trace")

st.title("Thread-Trace — Mood → Marketplace")

uploaded = st.file_uploader("Drag & drop your Pinterest / mood image", type=["jpg","jpeg","png"]) 

tab1, tab2, tab3 = st.tabs(["Inspiration", "AI Analysis", "Matches"])

with tab1:
	if uploaded:
		st.image(Image.open(uploaded), use_column_width=True)
	else:
		st.write("Demo inspirations (click to upload one locally if you want):")
		demo_list = matcher.list_demo_inspirations()
		if demo_list:
			cols = st.columns(min(3, len(demo_list)))
			for i, fname in enumerate(demo_list[:3]):
				cols[i].image(os.path.join("data/inspiration", fname), caption=fname)
		else:
			st.info("No demo images found in data/inspiration. Add 3–4 sample images named inspo1.jpg, inspo2.jpg, etc.")

with tab2:
	if uploaded:
		st.subheader("Quick AI Analysis")
		analysis = matcher.simulate_analysis(uploaded.name)
		for k, v in analysis.items():
			st.write(f"- {k}: {int(v*100)}%")
		with st.expander("Technical Breakdown"):
			st.write("Feature vector and nearest-neighbor search (simulated).")
	else:
		st.info("Upload a demo image to see simulated analysis.")

with tab3:
	st.header("Marketplace Matches")
	matches = []
	if uploaded:
		matches = matcher.load_matches_for(uploaded.name)
	else:
		# aggregate demo matches from the wizard map (or JSONs if present)
		for fname in matcher.WIZARD_MAP.keys():
			matches.extend(matcher.load_matches_for(fname))
		matches = matches[:8]

	if not matches:
		st.write("No matches found. Add demo matches JSON files to data/matches or map filenames in src/matcher.py")
	else:
		cols = st.columns(4)
		for i, item in enumerate(matches):
			# support both dict-items and legacy string paths
			if isinstance(item, dict):
				img = item.get("img")
				title = item.get("title", "")
				price = item.get("price", "")
				url = item.get("url", "")
				source = item.get("source", "")
			else:
				img = item
				title = os.path.basename(str(item))
				price = ""
				url = ""
				source = ""

			col = cols[i % 4]
			try:
				col.image(img, use_column_width=True)
			except Exception:
				col.write("(image missing) ")

			meta_line = ""
			if title:
				meta_line += f"**{title}**"
			if price:
				meta_line += f" — {price}"
			if source:
				meta_line += f" ({source})"
			if meta_line:
				col.write(meta_line)
			if url:
				col.markdown(f"[View listing]({url})")

